+export async function listTools() { return []; }
+export async function callTool() { throw new Error('not implemented'); }
+
+export async function listPrompts() {
+  return PROMPTS.map(({ name, description, arguments: args }) => ({
+    name,
+    description,
+    arguments: args
+  }));
+}
+
+function promptError(message, code = -32602) {
+  const error = new Error(message);
+  error.code = code;
+  return error;
+}
+
+function isMissing(value) {
+  return value === undefined || value === null || value === '';
+}
+
+export async function getPrompt(name, args = {}) {
+  const prompt = PROMPTS.find((p) => p.name === name);
+  if (!prompt) {
+    throw promptError(`Unknown prompt: ${name}`);
+  }
+
+  const allowed = new Set(prompt.arguments.map((a) => a.name));
+  for (const key of Object.keys(args)) {
+    if (!allowed.has(key)) {
+      throw promptError(`Unknown argument: ${key}`);
+    }
+  }
+
+  const values = { ...(DEFAULTS[name] || {}) };
+  for (const arg of prompt.arguments) {
+    const value = args[arg.name];
+    if (isMissing(value)) {
+      if (arg.required) {
+        throw promptError(`Missing required argument: ${arg.name}`);
+      }
+    } else {
+      values[arg.name] = value;
+    }
+  }
+
+  return render(prompt, values);
+}
+
+function render(prompt, values) {
+  if (prompt.name === 'summarize') {
+    const { topic, audience } = values;
+    return {
+      messages: [
+        {
+          role: 'user',
+          content: {
+            type: 'text',
+            text: `Summarize the topic "${topic}" for a ${audience} audience.`
+          }
+        }
+      ]
+    };
+  }
+  throw promptError(`Cannot render prompt: ${prompt.name}`);
+}
